def populate_order(apps, schema_editor):
    ProductParameter = apps.get_model("configurator", "ProductParameter")

    for product_id in (
        ProductParameter.objects
        .values_list("product_id", flat=True)
        .distinct()
    ):
        params = (
            ProductParameter.objects
            .filter(product_id=product_id)
            .order_by("id")  # or any existing implicit order
        )

        for index, param in enumerate(params):
            param.order = index
            param.save(update_fields=["order"])


